from collections import deque
left={(r,c) for r in range(20) for c in range(12) if grid[r][c]!=3}
comps=[]
while left:
 s=left.pop(); q=[s]; comp={s}
 while q:
  r,c=q.pop()
  for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
   if p in left:left.remove(p);comp.add(p);q.append(p)
 comps.append(comp)
[(len(x),(min(r for r,c in x),min(c for r,c in x),max(r for r,c in x),max(c for r,c in x))) for x in sorted(comps,key=lambda x:min(x))],sum(map(len,comps))

# Normalize pieces; map coordinates to values. Enumerate translations fitting target.
pieces=[]
for comp in comps:
 r0=min(r for r,c in comp);c0=min(c for r,c in comp)
 vals={(r-r0,c-c0):grid[r][c] for r,c in comp}
 pieces.append(vals)
placements=[]
for i,p in enumerate(pieces):
 h=max(r for r,c in p)+1;w=max(c for r,c in p)+1
 opts=[]
 for r0 in range(20-h+1):
  for c0 in range(8-w+1):
   cells={(r0+r,c0+c) for r,c in p}
   if cells <= target:
    opts.append((r0,c0,cells))
 placements.append(opts)
[(len(p),len(o)) for p,o in zip(pieces,placements)]

# candidate placements as bitsets for efficient exact cover
allps=[]
for i,(p,opts) in enumerate(zip(pieces,placements)):
 for r0,c0,cells in opts:
  if len(cells)!=len(p): continue
  allps.append({'i':i,'r0':r0,'c0':c0,'cells':frozenset(cells)})
cell_to_ps={cell:[] for cell in target}
for pi,pl in enumerate(allps):
 for cell in pl['cells']:cell_to_ps[cell].append(pi)
solutions=[]; nodes=0

def solve(covered, used, chosen):
 global nodes
 nodes+=1
 if len(covered)==len(target):
  if len(used)==len(pieces):solutions.append(chosen.copy())
  return
 best=None; candbest=None
 for cell in target-covered:
  cand=[pi for pi in cell_to_ps[cell] if allps[pi]['i'] not in used and not (allps[pi]['cells'] & covered)]
  if not cand:return
  if candbest is None or len(cand)<len(candbest):
   best=cell;candbest=cand
   if len(cand)==1:break
 for pi in candbest:
  pl=allps[pi]
  used.add(pl['i']); chosen.append(pi)
  solve(covered|pl['cells'],used,chosen)
  chosen.pop();used.remove(pl['i'])
  if len(solutions)>=100:return
solve(set(),set(),[])
len(solutions),nodes

def matpiece(i):
 p=pieces[i];h=max(r for r,c in p)+1;w=max(c for r,c in p)+1
 return '\n'.join(' '.join(str(p.get((r,c),'.')) for c in range(w)) for r in range(h))
for i,p in enumerate(pieces):print(i,len(p),matpiece(i),'\n')

# output placement tuples per sol
for i in range(len(pieces)):
 ps={ (allps[pi]['r0'],allps[pi]['c0']) for sol in solutions for pi in sol if allps[pi]['i']==i}
 print(i, len(ps), sorted(ps)[:30])
